"""Mutalia-e-Quran XII PDF111: p.108 — verses 33:14 (begun on p.107)–19 (33:20 continues onto p.109; recorded there). Run: python class12_quran_page111.py"""
from class12_quran_common import BOOK, Builder, rec, V


def p111():
    b = Builder()
    V(b, 33, 14, 'اور اگر ان پر اُس (مدینہ) کے اطراف سے (کفار کے لشکر) گھس آتے پھر اُن سے فتنہ (انگیزی) میں پڑنے کا کہا جاتا تو یقیناً وہ ایسا کر گزرتے اور اس میں صرف تھوڑی ہی دیر کرتے۔',
      'او که پر هغوی د هغې (مدینې) له اړخونو (د کافرانو لښکرې) ننوتې وای، بیا ورته د فتنې (اچولو) ویل شوي وای، نو یقیناً به یې کړې وای او په هغې کې به یې یوازې لږ ځنډ کړی وای.')
    V(b, 33, 15, 'اور یقیناً انھوں نے اس سے پہلے ضرور اللہ سے عہد کر رکھا تھا کہ وہ پیٹھ نہیں پھیریں گے اور اللہ سے کیے ہوئے عہد کے متعلق باز پرس ہو کر رہے گی۔',
      'او یقیناً هغوی له دې مخکې له الله سره ژمنه کړې وه چې شا به نه اړوي؛ او له الله سره د شوې ژمنې پوښتنه به خامخا کېږي.')
    V(b, 33, 16, 'آپ (صلی اللہ علیہ وعلیٰ آلہٖ واصحابہٖ وسلم) فرما دیجیے تمھیں بھاگنا ہرگز کوئی فائدہ نہ دے گا اگر تم موت سے یا قتل ہونے سے بھاگو اور اس صورت میں تم (زندگی کا) تھوڑی سی مدت کے سوا کچھ فائدہ نہ اٹھا سکو گے۔',
      'تاسو (صلی الله علیه وعلی آله واصحابه وسلم) ووایئ: تېښته به تاسو ته هېڅکله ګټه ونه رسوي که له مرګه یا له وژل کېدو وتښتئ؛ او په دې حالت کې به تاسو (د ژوند) له لږې مودې پرته هېڅ ګټه وانه خلئ.')
    V(b, 33, 17, 'آپ (صلی اللہ علیہ وعلیٰ آلہٖ واصحابہٖ وسلم) فرما دیجیے کون ہے جو تمھیں اللہ سے بچا سکے اگر وہ تمھیں کوئی نقصان پہنچانا چاہے یا تمھیں رحمت پہنچانا چاہے (تو کون اسے روک سکتا ہے) اور وہ لوگ اپنے لیے اللہ کو چھوڑ کر نہ کوئی حمایتی پائیں گے اور نہ کوئی مددگار۔',
      'تاسو (صلی الله علیه وعلی آله واصحابه وسلم) ووایئ: څوک دی چې تاسو له الله وساتي که هغه تاسو ته کوم زیان ورسول وغواړي یا تاسو ته رحمت ورسول وغواړي (نو څوک یې منع کولی شي)؟ او هغوی به د ځان لپاره له الله پرته نه کوم حمایتي ومومي او نه کوم مرستندوی.')
    V(b, 33, 18, 'یقیناً اللہ تم میں سے (جہاد سے) روکنے والوں کو جانتا ہے اور (انھیں بھی) جو اپنے بھائیوں سے کہتے ہیں کہ ہماری طرف آ جاؤ اور وہ جنگ میں شرکت نہیں کرتے مگر بہت ہی کم۔',
      'یقیناً الله له تاسو هغه (له جهاد) منع کوونکي پېژني، او (هغوی هم) چې خپلو وروڼو ته وايي: زموږ لوري ته راشئ؛ او هغوی په جګړه کې ګډون نه کوي مګر ډېر لږ.')
    V(b, 33, 19, '(منافقین) تمھارے بارے میں سخت بخیل ہیں تو جب خوف کا وقت آتا ہے تو آپ انھیں دیکھتے ہیں کہ وہ آپ کی طرف دیکھ رہے ہوتے ہیں اُن کی آنکھیں اس شخص کی طرح پھرتی ہیں جس پر موت کی غشی طاری ہو رہی ہو تو جب خوف ٹل جاتا ہے تو تمھیں تیز زبانوں سے طعنے دیتے ہیں مال (غنیمت) پر بڑے حریص ہیں یہ لوگ (درحقیقت) ایمان نہیں لائے پس اللہ نے اُن کے اعمال ضائع کر دیے اور یہ (بات) اللہ کے لیے (بہت) آسان ہے۔',
      '(منافقان) ستاسو په اړه ډېر بخیلان دي؛ نو کله چې د وېرې وخت راشي، ته یې وینې چې تا ته ګوري، سترګې یې د هغه چا په څېر ګرځي چې د مرګ بې‌هوښي پرې راغلې وي؛ نو کله چې وېره لاړه شي، په تېزو ژبو درته پېغورونه درکوي؛ پر مال (غنیمت) ډېر حریصان دي؛ دا خلک (په حقیقت کې) ایمان نه دي راوړي، نو الله د هغوی عملونه ضایع کړل؛ او دا (خبره) پر الله (ډېره) اسانه ده.')
    BOOK.save(111, [(11, rec(b, 11, 111, 111, pages_=[107, 108]))], issues=[{'id': 'mq12-pdf111', 'unit': 11, 'printedPage': 108,
               'description': 'Verse 33:14 begins on the last line of p.107; recorded here. Verse 33:20 begins on the last two lines of p.108 and is recorded with p.109.'}])


if __name__ == '__main__':
    p111()
